package edu.fuzzy;
import java.util.*;
import java.nio.file.*;
import java.io.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.security.access.AccessDeniedException;
import static edu.fuzzy.Db.*;
import static edu.fuzzy.AuditProtocol.*;
@Service
public class WorkflowService {
 private final ObjectStore objects;private final Db db;private final CryptoService crypto;private final AuditProtocol protocol;private final ObjectMapper json;private final boolean demo;
 public WorkflowService(Db db,CryptoService crypto,AuditProtocol protocol,ObjectMapper json,ObjectStore objects,@Value("${fuzzy.demo}")boolean demo){this.db=db;this.crypto=crypto;this.protocol=protocol;this.json=json;this.demo=demo;this.objects=objects;}
 public Map<String,Object> file(String id){return db.one("select f.*,u.display_name owner_name from stored_file f join app_user u on u.id=f.owner_id where f.id=?",id);}
 public void owner(Map<String,Object>u,Map<String,Object>f){AccountService.approved(u);if(!str(u,"id").equals(str(f,"owner_id")))throw new AccessDeniedException("Only this file's owner may perform this action.");}
 public boolean canDownload(Map<String,Object>u,Map<String,Object>f){if(!str(u,"approval").equals("APPROVED")||!str(u,"role").equals("USER"))return false;if(str(u,"id").equals(str(f,"owner_id")))return true;return !db.jdbc.queryForList("select id from share_request where file_id=? and requester_id=? and request_state='APPROVED'",str(f,"id"),str(u,"id")).isEmpty();}
 @Transactional public String upload(Map<String,Object>u,MultipartFile input,String previous)throws Exception{
  AccountService.approved(u);long start=System.nanoTime();if(input==null||input.isEmpty()||input.getSize()>10485760)throw new IllegalArgumentException("Upload a nonempty file, maximum 10 MiB.");
  String name=input.getOriginalFilename();if(name==null||name.isBlank()||name.length()>240||name.contains("/")||name.contains("\\")||name.contains("..")||name.chars().anyMatch(c->c<32))throw new IllegalArgumentException("Use a simple filename without paths or traversal sequences.");
  db.one("select id from app_user where id=? for update",str(u,"id"));String id=id(),family=id;int version=1;
  if(previous!=null&&!previous.isBlank()){var old=file(previous);owner(u,old);family=str(old,"family_id");version=db.jdbc.queryForObject("select max(file_version) from stored_file where family_id=?",Integer.class,family)+1;}
  byte[] key=crypto.random(32);byte[] envelope=crypto.encrypt(input.getBytes(),key,id+":"+version);Manifest manifest=protocol.manifest(id,version,envelope);String metadata=json.writeValueAsString(manifest);objects.put(id,envelope);
  try{db.jdbc.update("insert into stored_file(id,owner_id,display_name,file_version,family_id,original_length,envelope_length,wrapped_key,manifest_json,manifest_checksum,created_at,upload_ms,demo_owned) values(?,?,?,?,?,?,?,?,?,?,?,?,?)",id,str(u,"id"),name,version,family,input.getSize(),envelope.length,crypto.wrap(key,"file:"+id),metadata,CryptoService.hash(metadata.getBytes(java.nio.charset.StandardCharsets.UTF_8)),now(),ms(start),demo);db.notice(str(u,"id"),"Encrypted upload stored: "+name+" (version "+version+"). Trusted verification manifest created.");}catch(Exception e){objects.delete(id);throw e;}return id;
 }
 public byte[] download(Map<String,Object>u,String id)throws Exception{var f=file(id);if(!canDownload(u,f))throw new AccessDeniedException("Download denied: you need owner-approved access.");try{return crypto.decrypt(objects.read(id),crypto.unwrap(str(f,"wrapped_key"),"file:"+id),id+":"+num(f,"file_version"));}catch(Exception e){throw new IllegalArgumentException("Download blocked: current ciphertext is missing, truncated or fails AES-GCM authentication. Re-upload the original as a new version.");}}
 @Transactional public void requestAccess(Map<String,Object>u,String id){AccountService.approved(u);var f=file(id);if(str(f,"owner_id").equals(str(u,"id")))throw new IllegalArgumentException("You already own this file.");db.one("select id from app_user where id=? for update",str(u,"id"));if(!db.jdbc.queryForList("select id from share_request where file_id=? and requester_id=?",id,str(u,"id")).isEmpty())throw new IllegalArgumentException("An access request already exists. See its status in request history.");db.jdbc.update("insert into share_request(id,file_id,requester_id,request_state,created_at) values(?,?,?,?,?)",id(),id,str(u,"id"),"PENDING",now());db.notice(str(f,"owner_id"),str(u,"display_name")+" requested access to "+str(f,"display_name"));}
 @Transactional public void decideShare(Map<String,Object>u,String id,String decision){if(!Set.of("APPROVED","REJECTED","REVOKED").contains(decision))throw new IllegalArgumentException("Invalid decision");var r=db.one("select * from share_request where id=? for update",id);var f=file(str(r,"file_id"));owner(u,f);String state=str(r,"request_state");if(!(state.equals("PENDING")&& !decision.equals("REVOKED"))&&!(state.equals("APPROVED")&&decision.equals("REVOKED")))throw new IllegalArgumentException("Invalid access-request transition.");db.jdbc.update("update share_request set request_state=?,decided_at=? where id=?",decision,now(),id);db.notice(str(r,"requester_id"),"Access "+decision+" for "+str(f,"display_name")+". Access is application-mediated; no AES key is delivered. Verification object: "+str(f,"id")+" / version "+num(f,"file_version"));}
 @Transactional public String requestAudit(Map<String,Object>u,String id,String mode){var f=file(id);owner(u,f);if(!Set.of("FULL","SAMPLED").contains(mode))throw new IllegalArgumentException("Choose FULL or SAMPLED.");String audit=id();db.jdbc.update("insert into audit_record(id,file_id,requester_id,audit_mode,audit_state,created_at) values(?,?,?,?,?,?)",audit,id,str(u,"id"),mode,"REQUESTED",now());return audit;}
 public Map<String,Object> audit(Map<String,Object>u,String id){var a=db.one("select a.*, f.display_name, f.owner_id, f.file_version from audit_record a join stored_file f on f.id=a.file_id where a.id=?",id);if(str(u,"role").equals("USER")){AccountService.approved(u);if(!str(a,"requester_id").equals(str(u,"id")))throw new AccessDeniedException("This audit belongs to another user.");}return a;}
 private Map<String,Object> locked(String id,String state){var a=db.one("select * from audit_record where id=? for update",id);if(!str(a,"audit_state").equals(state))throw new IllegalArgumentException("Audit is "+str(a,"audit_state")+"; this transition cannot be replayed.");return a;}
 public Manifest manifest(Map<String,Object>f)throws Exception{String text=str(f,"manifest_json");if(!CryptoService.hash(text.getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(str(f,"manifest_checksum")))throw new IllegalStateException("Trusted manifest checksum mismatch. Restore trusted metadata.");return json.readValue(text,Manifest.class);}
 @Transactional public void challenge(Map<String,Object>u,String id)throws Exception{AccountService.requireRole(u,"TPA");long t=System.nanoTime();var a=locked(id,"REQUESTED");var c=protocol.challenge(id,manifest(file(str(a,"file_id"))),str(a,"audit_mode"),now());db.jdbc.update("update audit_record set challenge_json=?,audit_state='CHALLENGED',challenge_ms=? where id=?",json.writeValueAsString(c),ms(t),id);}
 @Transactional public void respond(Map<String,Object>u,String id)throws Exception{AccountService.requireRole(u,"CLOUD");long t=System.nanoTime();var a=locked(id,"CHALLENGED");Challenge c=json.readValue(str(a,"challenge_json"),Challenge.class);if(now()>c.expiresAt()){db.jdbc.update("update audit_record set audit_state='EXPIRED', detail='Challenge expired before response' where id=?",id);return;}
  try{Response r=objects.respond(protocol,c);db.jdbc.update("update audit_record set response_json=?,audit_state='RESPONDED',response_ms=? where id=?",json.writeValueAsString(r),ms(t),id);}catch(IOException e){db.jdbc.update("update audit_record set audit_state='ERROR',detail=?,response_ms=? where id=?","Current cloud object is missing or unreadable; no proof generated.",ms(t),id);db.notice(str(a,"requester_id"),"Audit ERROR: cloud object missing/unreadable. Audit "+id);}
 }
 @Transactional public void verify(Map<String,Object>u,String id)throws Exception{AccountService.requireRole(u,"TPA");long t=System.nanoTime();var a=locked(id,"RESPONDED");Challenge c=json.readValue(str(a,"challenge_json"),Challenge.class);Response r=json.readValue(str(a,"response_json"),Response.class);Result result=protocol.verify(c,r,manifest(file(str(a,"file_id"))),now());String state=now()>c.expiresAt()?"EXPIRED":result.passed()?"VERIFIED_PASS":"VERIFIED_FAIL";db.jdbc.update("update audit_record set result_json=?,audit_state=?,detail=?,verify_ms=?,verified_at=? where id=?",json.writeValueAsString(result),state,result.reason(),ms(t),now(),id);db.notice(str(a,"requester_id"),"Audit "+state+" for "+str(file(c.fileId()),"display_name")+". "+result.reason());}
 @Transactional public void tamper(Map<String,Object>u,String id,int block)throws Exception{AccountService.requireRole(u,"CLOUD");if(!demo)throw new AccessDeniedException("Corruption controls are disabled outside demo mode.");var f=file(id);if(!Boolean.TRUE.equals(f.get("demo_owned"))&&!str(f,"demo_owned").equals("1"))throw new AccessDeniedException("Only demo-owned objects can be corrupted.");long len=num(f,"envelope_length");if(block<0||(long)block*BLOCK_SIZE>=len)throw new IllegalArgumentException("Choose an existing block index.");long offset=(long)block*BLOCK_SIZE+Math.min(20,len-(long)block*BLOCK_SIZE-1);objects.flip(id,offset);db.jdbc.update("insert into tamper_event(id,file_id,actor_id,block_index,created_at) values(?,?,?,?,?)",id(),id,str(u,"id"),block,now());db.notice(str(f,"owner_id"),"Demo corruption recorded in ciphertext block "+block+". Run a FULL audit; re-upload original bytes to recover a new version.");}
 public <T>T decode(String s,Class<T>type)throws Exception{return s==null||s.isBlank()?null:json.readValue(s,type);}
 private static double ms(long start){return (System.nanoTime()-start)/1000000.0;}
}
